INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('20a38aae-d6eb-5248-bb5f-e6bda3411ff7'::uuid, '83d901ae-58ea-5173-b890-3fc4b03cd792'::uuid, 'Nos réalisations', 'Un renseignement ? Une Question sur nos prestations ? LPGM Ingénierie est un acteur incontournable du BTP et de la construction. Laboratoire spécialisé dans les études des sols, des matériaux issus de la construction, des ouvrages existants, des routes et des risques naturels.', '["https://www.lpgm-ingenierie.com/height=319/image/536851708/802aa897-299f-4a97-8aca-cd4e72932a59.jpg"]'::jsonb, 'https://www.lpgm-ingenierie.com/height=319/image/536851708/802aa897-299f-4a97-8aca-cd4e72932a59.jpg', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.4.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6194a295-e5f5-54b8-b4a8-bc8d4b3fa7e2'::uuid, '83d901ae-58ea-5173-b890-3fc4b03cd792'::uuid, 'MOOC Gestion projet - Centrale Lille', 'Enseignant - ENSI et EMSI L’objectif du laboratoire LPGM Ingénierie est de satisfaire les besoins de ses clients, des prescripteurs et de l’ensemble des intervenants dans les projets de construction en BTP .', '["https://www.lpgm-ingenierie.com/height=160/image/536851708/802aa897-299f-4a97-8aca-cd4e72932a59.jpg"]'::jsonb, 'https://www.lpgm-ingenierie.com/height=160/image/536851708/802aa897-299f-4a97-8aca-cd4e72932a59.jpg', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.4.4' LIMIT 1));
