INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('3bf1ac25-3549-5597-9826-9439ad41545f'::uuid, '83d901ae-58ea-5173-b890-3fc4b03cd792'::uuid, 'Il dépend de votre projet , donc du type de mission dont vous allez avoir besoin .', 'Chaque projet, chaque terrain est différent, votre offre doit donc être adaptée et personnalisée !', '["https://www.lpgm-ingenierie.com/height=271/image/536852147/e7dffe75-5981-476c-80c6-434deea6cebe.jpg"]'::jsonb, 'https://www.lpgm-ingenierie.com/height=271/image/536852147/e7dffe75-5981-476c-80c6-434deea6cebe.jpg', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.4.4' LIMIT 1));
