INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2f78695b-b94e-5429-944d-4754075084fa'::uuid, '05fb5ac0-0101-5d1a-bc98-f28175c8e1b6'::uuid, 'Exemple de programme pour un séjour canyoning dans l’Anti-Atlas', 'Un séjour type consacré au canyoning près d’Agadir s’organise souvent sur plusieurs jours, avec hébergement en pension complète dans des structures locales conviviales. Les journées commencent généralement par une initiation ou un rappel des techniques essentielles auprès de moniteurs diplômés. Puis les activités s’enchaînent entre baignades, passages techniques, tyroliennes et escalades naturelle', '["https://discoveragadir.com/wp-content/uploads/2023/03/cropped-Untitled-1-01.png"]'::jsonb, 'https://discoveragadir.com/wp-content/uploads/2023/03/cropped-Untitled-1-01.png', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
