INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('1a701100-f67b-5ad3-8614-3f806723662c'::uuid, 'fdc7c20c-491b-556a-b5ab-2962cd9eabc8'::uuid, 'Projet Etanchéité toiture THEATRE MARTIL- MAROC', 'En étroite collaboration avec la société ROUANDI et le bureau d’étude SOCOTEC, SMETS est heureux d''avoir pu apporter son expertise en étanchéité liquide au théâtre de la ville de Martil. Nous remercions vivement le théâtre pour la confiance qu''il nous a accordée.', '["https://smets.ma/wp-content/uploads/2021/02/batiment.png"]'::jsonb, 'https://smets.ma/wp-content/uploads/2021/02/batiment.png', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
